@startuml

class Airline {
  + ID : string
}

class Flight {
  + ID : string
  + DepartureTime : time
  + ArrivalTime : time
}

class Airport {
  + ID : string
}

class Aircraft {
  + Type : string
  + IsWorking : boolean
  + IsAirborne : boolean
}

class Pilot {
  + ExperienceLevel : int
}

class RoleRequirement {
  + Role : string
  + RequiredCount : int
}

Airline "1" -- "*" Flight
Airline "1" -- "*" Aircraft
Flight "0..*" -- "1" Airport : departure
Flight "0..*" -- "1" Airport : arrival
Flight "0..*" -- "1" Pilot : captain
Flight "0..*" -- "1" Pilot : co-pilot
Flight "0..*" -- "1" Aircraft
Aircraft "1" -- "*" RoleRequirement

@enduml

